<canvas id="canvas" width="600" height="600"></canvas>
<script>
const canvas = document.getElementById('canvas');
const ctx = canvas.getContext('2d');
const W = canvas.width;
const H = canvas.height;

// Physics constants
const GRAVITY = 0.5;
const DAMPING = 0.99;
const BOUNCE = 0.6;
const ITERATIONS = 10; // constraint solver iterations

// Die size
const DIE_SIZE = 80;

// Verlet point
class Point {
  constructor(x, y) {
    this.x = x;
    this.y = y;
    this.ox = x; // old position
    this.oy = y;
    this.pinned = false;
  }

  update() {
    if (this.pinned) return;
    const vx = (this.x - this.ox) * DAMPING;
    const vy = (this.y - this.oy) * DAMPING;
    this.ox = this.x;
    this.oy = this.y;
    this.x += vx;
    this.y += vy + GRAVITY;
  }

  constrain() {
    // Ground
    if (this.y > H - 10) {
      this.y = H - 10;
      this.oy = this.y + (this.y - this.oy) * BOUNCE;
    }
    // Walls
    if (this.x < 10) {
      this.x = 10;
      this.ox = this.x + (this.x - this.ox) * BOUNCE;
    }
    if (this.x > W - 10) {
      this.x = W - 10;
      this.ox = this.x + (this.x - this.ox) * BOUNCE;
    }
    // Ceiling
    if (this.y < 10) {
      this.y = 10;
      this.oy = this.y + (this.y - this.oy) * BOUNCE;
    }
  }
}

// Distance constraint
class Constraint {
  constructor(p1, p2, distance) {
    this.p1 = p1;
    this.p2 = p2;
    this.distance = distance;
  }

  solve() {
    const dx = this.p2.x - this.p1.x;
    const dy = this.p2.y - this.p1.y;
    const dist = Math.sqrt(dx * dx + dy * dy);
    if (dist === 0) return;
    const diff = (this.distance - dist) / dist * 0.5;
    const ox = dx * diff;
    const oy = dy * diff;
    if (!this.p1.pinned) {
      this.p1.x -= ox;
      this.p1.y -= oy;
    }
    if (!this.p2.pinned) {
      this.p2.x += ox;
      this.p2.y += oy;
    }
  }
}

// Create die: 4 corners + center
const points = [];
const constraints = [];

const cx = W / 2;
const cy = 150;
const half = DIE_SIZE / 2;

// Corners
const p0 = new Point(cx - half, cy - half);
const p1 = new Point(cx + half, cy - half);
const p2 = new Point(cx + half, cy + half);
const p3 = new Point(cx - half, cy + half);
// Center
const pc = new Point(cx, cy);

points.push(p0, p1, p2, p3, pc);

// Edge constraints
constraints.push(new Constraint(p0, p1, DIE_SIZE));
constraints.push(new Constraint(p1, p2, DIE_SIZE));
constraints.push(new Constraint(p2, p3, DIE_SIZE));
constraints.push(new Constraint(p3, p0, DIE_SIZE));

// Diagonal constraints (corner to center)
const diag = Math.sqrt(2) * half;
constraints.push(new Constraint(p0, pc, diag));
constraints.push(new Constraint(p1, pc, diag));
constraints.push(new Constraint(p2, pc, diag));
constraints.push(new Constraint(p3, pc, diag));

// Mouse interaction
let dragging = null;
let mouse = { x: 0, y: 0 };

canvas.addEventListener('mousedown', (e) => {
  const rect = canvas.getBoundingClientRect();
  mouse.x = e.clientX - rect.left;
  mouse.y = e.clientY - rect.top;

  // Find closest point
  let closest = null;
  let closestDist = Infinity;
  for (const p of points) {
    const dx = p.x - mouse.x;
    const dy = p.y - mouse.y;
    const dist = Math.sqrt(dx * dx + dy * dy);
    if (dist < closestDist && dist < DIE_SIZE) {
      closestDist = dist;
      closest = p;
    }
  }
  if (closest) {
    dragging = closest;
    dragging.pinned = true;
  }
});

canvas.addEventListener('mousemove', (e) => {
  const rect = canvas.getBoundingClientRect();
  mouse.x = e.clientX - rect.left;
  mouse.y = e.clientY - rect.top;
});

canvas.addEventListener('mouseup', () => {
  if (dragging) {
    dragging.pinned = false;
    dragging = null;
  }
});

// Update mouse position of dragged point
function updateDrag() {
  if (dragging) {
    dragging.x = mouse.x;
    dragging.y = mouse.y;
  }
}

// Physics step
function step() {
  updateDrag();
  for (const p of points) p.update();
  for (let i = 0; i < ITERATIONS; i++) {
    for (const c of constraints) c.solve();
    for (const p of points) p.constrain();
  }
}

// Draw die
function draw() {
  ctx.clearRect(0, 0, W, H);

  // Draw die body
  ctx.beginPath();
  ctx.moveTo(p0.x, p0.y);
  ctx.lineTo(p1.x, p1.y);
  ctx.lineTo(p2.x, p2.y);
  ctx.lineTo(p3.x, p3.y);
  ctx.closePath();
  ctx.fillStyle = '#e94560';
  ctx.fill();
  ctx.strokeStyle = '#fff';
  ctx.lineWidth = 2;
  ctx.stroke();

  // Draw center dot
  ctx.beginPath();
  ctx.arc(pc.x, pc.y, 8, 0, Math.PI * 2);
  ctx.fillStyle = '#fff';
  ctx.fill();
}

// Main loop
function loop() {
  step();
  draw();
  requestAnimationFrame(loop);
}

loop();
</script>
</body>
